/* ---------------- সব একত্র: T[lang][key] ---------------- */
const merge = (...parts) => {
  const out = {};
  parts.forEach((p) =>
    Object.entries(p).forEach(([lg, d]) => { out[lg] = { ...(out[lg] || {}), ...d }; })
  );
  return out;
};
export const T = merge(TR_MAIN, TR_MENU, TR_AUTH, TR_SYS, TR_EXTRA, TR_MORE, TR_DEP);

/* খোঁজার ক্রম: ভাষা -> (zhT হলে zh) -> English -> কী নিজে */
const FALLBACK = { zhT: "zh" };
export const translate = (lang, k) =>
  T[lang]?.[k] ?? T[FALLBACK[lang]]?.[k] ?? T.en?.[k] ?? k;

/* ---------------- ভাষা বাছাইয়ের ড্রপডাউন (সব পেজে এটাই ব্যবহার হবে) ---------------- */
export function LangPicker({ lang, setLang }) {
  const [open, setOpen] = useState(false);
  const cur = LANGS.find((l) => l[0] === lang) || LANGS[1];
  return (
    <div className="cx-lgw">
      <button className="cx-lang" onClick={() => setOpen(!open)}>{cur[1]} <span className="cx-fl">{cur[2]}</span></button>
      {open && (
        <>
          <div className="cx-lgback" onClick={() => setOpen(false)} />
          <div className="cx-lgm">
            {LANGS.map(([k, n, f]) => (
              <button key={k} className={k === lang ? "on" : ""} onClick={() => { setLang(k); setOpen(false); }}>
                <span>{n}</span><span className="cx-fl">{f}</span>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}
